import{c as l,Z as e,Q as r,j as s,m as n,o as i}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"桃夭","description":"","frontmatter":{"title":"桃夭","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/3.md","filePath":"books/shici/shijing/3.md"}'),h={name:"books/shici/shijing/3.md"};function c(d,a,u,_,m,p){const o=e("PoemAuthor"),t=e("PoemNav");return r(),s("div",null,[a[0]||(a[0]=n('<h1 id="桃夭" tabindex="-1">桃夭 <a class="header-anchor" href="#桃夭" aria-label="Permalink to &quot;桃夭&quot;">​</a></h1><p><strong>《诗经·周南》</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>桃之夭夭，灼灼其华。之子于归，宜其室家。 桃之夭夭，有蕡其实。之子于归，宜其家室。 桃之夭夭，其叶蓁蓁。之子于归，宜其家人。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>夭夭：茂盛而美丽的样子</li><li>灼灼：鲜明的样子，形容花开繁盛</li><li>华：同&quot;花&quot;</li><li>之子：这位姑娘</li><li>于归：出嫁</li><li>宜：和顺，使……和睦</li><li>室家：家庭</li><li>蕡：果实硕大的样子</li><li>蓁蓁：树叶茂盛的样子</li><li>家人：一家人</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>桃花怒放千万朵，色彩鲜艳红似火。这位姑娘要出嫁，喜气洋洋归夫家。 桃花怒放千万朵，果实累累大又多。这位姑娘要出嫁，早生贵子后嗣旺。 桃花怒放千万朵，绿叶茂盛永不落。这位姑娘要出嫁，齐心协手家和睦。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《桃夭》是《诗经·周南》中的名篇，是一首祝贺年轻女子出嫁的贺婚诗。全诗以桃花起兴，以桃花的艳丽比喻新娘的美貌，以桃实的丰硕象征多子多福，以桃叶的茂盛祝愿家庭兴旺。三章结构相似，层层递进，从花到果再到叶，寓意从新婚到生育再到家族繁荣，表达了对新娘的美好祝福。此诗开创了以桃花比喻美人的传统，对后世文学影响深远，&quot;夭桃秾李&quot;&quot;人面桃花&quot;等典故皆源于此。</p>',10)),i(o,{name:"《诗经》",years:"西周初年至春秋中叶",desc:"中国最早的诗歌总集，收录了西周初年至春秋中叶（前11世纪至前6世纪）的诗歌305篇，分为“风”“雅”“颂”三部分。《诗经》内容丰富，反映了周代社会生活的方方面面，是中国现实主义文学的源头。",link:"/books/shici/shijing","is-shijing":""}),i(t)])}const f=l(h,[["render",c]]);export{b as __pageData,f as default};
